-- This code has been fully generated by an AI.
--
-- Initial schema. Times are Unix seconds (UTC); tz_offset_s places an
-- activity on the local calendar. Metrics that were not recorded are NULL.

CREATE TABLE activity (
    id                  INTEGER PRIMARY KEY,
    name                TEXT,
    sport               TEXT    NOT NULL,
    sub_sport           TEXT    NOT NULL,
    start_time          INTEGER NOT NULL,
    tz_offset_s         INTEGER NOT NULL DEFAULT 0,
    distance_m          REAL    NOT NULL DEFAULT 0,
    timer_s             REAL    NOT NULL DEFAULT 0,
    elapsed_s           REAL    NOT NULL DEFAULT 0,
    ascent_m            INTEGER,
    descent_m           INTEGER,
    avg_speed_mps       REAL,
    max_speed_mps       REAL,
    avg_heart_rate      INTEGER,
    max_heart_rate      INTEGER,
    avg_power           INTEGER,
    max_power           INTEGER,
    avg_cadence         INTEGER,
    device_manufacturer INTEGER,
    device_product      INTEGER,
    device_serial       INTEGER,
    min_lat             REAL,
    min_lon             REAL,
    max_lat             REAL,
    max_lon             REAL,
    -- Version of the import pipeline that derived stream, track and metrics;
    -- a higher pipeline version re-derives them from the raw file.
    analysis_version    INTEGER NOT NULL,
    created_at          INTEGER NOT NULL,
    updated_at          INTEGER NOT NULL
);

CREATE INDEX activity_start_time ON activity (start_time);
CREATE INDEX activity_sport ON activity (sport, start_time);

-- Natural keys of the recordings an activity was built from, e.g.
-- source 'fit' with key 'fit:1:3616025585:1792502945' or 'sha256:…',
-- later also source 'garmin' with the Garmin Connect activity id.
CREATE TABLE activity_source (
    id          INTEGER PRIMARY KEY,
    activity_id INTEGER NOT NULL REFERENCES activity (id) ON DELETE CASCADE,
    source      TEXT    NOT NULL,
    source_key  TEXT    NOT NULL,
    sha256      TEXT,
    origin      TEXT,
    imported_at INTEGER NOT NULL,
    UNIQUE (source, source_key)
);

CREATE INDEX activity_source_activity ON activity_source (activity_id);

-- Full-resolution channels for detail charts (gzip-compressed JSON).
CREATE TABLE activity_stream (
    activity_id INTEGER PRIMARY KEY REFERENCES activity (id) ON DELETE CASCADE,
    encoding    TEXT NOT NULL,
    data        BLOB NOT NULL
);

-- Simplified geometry for lists and the heatmap (encoded polyline, 1e-5 precision).
CREATE TABLE activity_track (
    activity_id INTEGER PRIMARY KEY REFERENCES activity (id) ON DELETE CASCADE,
    points      INTEGER NOT NULL,
    polyline    TEXT    NOT NULL
);
